INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'far-south-overnight-power-cut-for-upgrades-2026-09-26',
  'Overnight power cut on 10 October for electricity upgrades across the Southern and Far South suburbs',
  'Utilities', '2026-09-26', 'IOL / Cape Argus',
  'https://iol.co.za/capeargus/news/2026-09-26-cape-towns-major-10-hour-power-outage-is-not-tonight-heres-when-it-will-happen/',
  'Large parts of the Southern and Far South suburbs will be without electricity from 20:00 on Saturday 10 October until 06:00 on Sunday 11 October while the City upgrades the network.',
  'The City of Cape Town has scheduled a planned electricity interruption for a wide area of the Southern and Far South suburbs. Power is due to go off at 20:00 on Saturday 10 October and come back by 06:00 on Sunday 11 October, although the City says supply may return sooner if the work finishes early.

Areas listed include Muizenberg, St James, Kalk Bay, Clovelly, Sun Valley, Fish Hoek, Glencairn, Simon''s Town, Noordhoek, Kommetjie, Ocean View, Masiphumelele, Scarborough and Tokai, plus Lakeside, Kirstenhof, Steenberg, Lavender Hill, Seawinds, Parkwood, Lotus River, Grassy Park and Vrygrond, as well as sections of Strandfontein, Ottery and Southfield. The City notes that a few places on its outage map may keep their power, while some neighbouring streets not on the list could also be affected.

According to the City, maintenance originally planned for 19 September was postponed and folded into this single, larger shutdown so that resources and funding are used more efficiently and residents face one interruption instead of several.

Residents should treat all wiring and installations as live for the whole period and switch appliances off beforehand so they are not damaged by a surge when supply is restored. Queries can go to the City call centre on 0860 103 089.',
  NULL, NULL, NULL,
  '["https://iol.co.za/capeargus/news/2026-09-26-cape-towns-major-10-hour-power-outage-is-not-tonight-heres-when-it-will-happen/", "https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/City-advises-of-critical-electricity-upgrades-in-large-parts-of-Southern-and-Far"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'faure-treatment-plant-offline-water-works-2026-09-25',
  'Faure treatment plant offline until Friday evening as City asks residents to use less water',
  'Utilities', '2026-09-25', 'City of Cape Town',
  'https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/Planned-water-supply-maintenance-for-28-September-to-2-October?category=Media%20releases',
  'The Faure Water Treatment Plant is shut for maintenance until 18:00 on Friday 2 October, with local water work and pressure tests continuing in several suburbs this week.',
  'The City of Cape Town has taken the Faure Water Treatment Plant out of service from 08:00 on Monday 28 September, with maintenance due to end at 18:00 on Friday 2 October. Teams are servicing filter valves, swapping out pumps and valves, working on the chlorine pumps and checking the inlet chambers. Supply is being routed in from the Steenbras and Blackheath bulk pipelines in the meantime, and the City is asking all residents to cut back on water use until the plant is running again.

Smaller jobs are also planned around the metro. On Thursday 1 October, water meter installation on Long Street in the CBD may interrupt supply between 09:00 and 18:00, and zero-pressure tests are scheduled in parts of Tamboerskloof, Gardens and Schotsche Kloof. On Chapman''s Peak Drive in Hout Bay, pipe replacement will cause intermittent shutoffs on weekdays from 07:30 to 17:00 until 3 December.

The City recommends keeping a supply of water in clean, sealed containers before any planned interruption and leaving taps closed while the water is off, to avoid losses or damage when it returns. Water may look cloudy for a while after supply is restored because of trapped air.',
  NULL, NULL, NULL,
  '["https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/Planned-water-supply-maintenance-for-28-September-to-2-October?category=Media%20releases", "https://www.capetownetc.com/news/planned-water-maintenance-work-leads-to-supply-disruptions-across-cape-town/"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'city-seeks-partner-faure-water-reuse-scheme-2026-09-29',
  'City opens tender for a private partner to build the Faure wastewater-to-drinking-water scheme',
  'Utilities', '2026-09-29', 'IOL / Cape Argus',
  'https://iol.co.za/capeargus/news/2026-09-29-cape-town-seeks-private-partner-for-r283bn-faure-water-reuse-scheme/',
  'Cape Town has started a two-stage procurement for the Faure New Water Scheme, a R2.83 billion plan to purify treated wastewater into drinking water, with first submissions due by 26 February 2027.',
  'The City of Cape Town has formally started looking for a private company to finance, design, build, run and maintain the Faure New Water Scheme. The project will take wastewater from the upgraded Zandvliet treatment works and use advanced purification to turn it into drinking water that meets local and international standards.

IOL reports the scheme is valued at R2.83 billion and is expected to produce between 70 and 100 million litres a day once running. The City says it is one part of its goal of adding 300 million litres a day from new water sources by the mid-2030s. Council approved a public-private partnership approach for the project in December 2025.

Procurement will run in two rounds. The first, a request for qualifications, tests whether bidders have the technical, financial and operational ability to deliver, and closes on 26 February 2027 according to IOL. Shortlisted parties will then be invited to submit full proposals in the second half of 2027.

The City''s water and sanitation mayoral committee member described the launch of procurement as an important step towards a new and reliable drinking water source for the city.',
  NULL, NULL, NULL,
  '["https://iol.co.za/capeargus/news/2026-09-29-cape-town-seeks-private-partner-for-r283bn-faure-water-reuse-scheme/", "https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/City-begins-procurement-for-Faure-New-Water-Scheme?category=Media%20releases"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'short-term-letting-bylaw-comment-closes-2026-09-28',
  'Comment on Cape Town''s draft short-term letting by-law closes on 5 October',
  'Business', '2026-09-28', 'GroundUp',
  'https://groundup.org.za/article/new-by-law-puts-the-brakes-on-airbnb-in-cape-town/',
  'Residents and hosts have until 5 October to comment on a draft City by-law that would make short-term rentals register and could move many onto commercial property rates from July 2027.',
  'The City of Cape Town''s draft Short-Term Letting By-law is open for public comment until 5 October. Under the proposal, any home advertised on Airbnb, Booking.com, LekkeSlaap or similar sites would need City registration, and the listing would have to display its registration number.

The draft also sets a rating rule. If a property can be booked as a short-term rental on more than half the days in a year, which works out to roughly 183 nights or more, it would be classed as commercial and charged at commercial rates. Properties let out for less than half the year could stay on residential rates if they meet the City''s requirements. Both GroundUp and IOL report that any change in rating category would apply from 1 July 2027, using data from the new registration system.

GroundUp gives the example of an inner-city property valued at R2.8 million, whose monthly rates would go from about R1,274 on the residential tariff to about R3,945 on the commercial tariff. It also reports that Cape Town has more than 27,000 short-term rentals listed on Airbnb.

Anyone who wants to have a say can submit comments through the City''s website before the deadline.',
  NULL, NULL, NULL,
  '["https://groundup.org.za/article/new-by-law-puts-the-brakes-on-airbnb-in-cape-town/", "https://iol.co.za/capeargus/news/2026-09-07-cape-town-airbnb-style-letting-rules-face-test-over-long-term-housing-supply/"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'samora-machel-roadworks-until-mid-december-2026-09-30',
  'Stormwater and road works in Samora Machel expected to cause delays until mid-December',
  'Traffic', '2026-09-30', 'City of Cape Town',
  'https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/Residents-advised-of-roadworks-in-Samora-Machel?category=Media%20releases',
  'The City is replacing stormwater pipes and resurfacing Oliver Tambo Avenue and Anton Fransch Street in Samora Machel, with work running Monday to Saturday until mid-December.',
  'Motorists in Samora Machel should plan for delays while City of Cape Town crews work on the section of Oliver Tambo Avenue running from Lillian Ngoyi Drive to Jakes Gerwel Drive, as well as on Anton Fransch Street from Ruth First Street to the end of the road. Work has already started and is planned to continue until mid-December 2026.

Crews will be on site from Monday to Saturday between 07:30 and 17:00. The job involves laying bigger underground stormwater pipes in place of the existing ones, building more catch pits and manholes, fixing sidewalks and resurfacing the road. The City says the drainage upgrade will help the area cope with heavier flows when it rains.

Traffic in both directions on Oliver Tambo Avenue will be affected, and the intersection with Jakes Gerwel Drive is likely to be congested. Flag staff will guide drivers through temporary diversions. People living and trading nearby can expect construction noise during working hours, and the City warns that vehicles left in the way of the work will be towed.',
  NULL, NULL, NULL,
  '["https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/Residents-advised-of-roadworks-in-Samora-Machel?category=Media%20releases", "https://smilefm.co.za/roadworks-underway-in-samora-machel-2/"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'beach-lowering-muizenberg-fish-hoek-hout-bay-2026-09-25',
  'Sand-lowering machines on Muizenberg, Fish Hoek and Hout Bay beaches from 1 October',
  'Community', '2026-09-25', 'City of Cape Town',
  'https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/Annual-beach-lowering-at-Muizenberg-Fish-Hoek-and-Hout-Bay?category=Media%20releases',
  'The City starts its yearly beach-lowering work at Muizenberg, Fish Hoek and Hout Bay on 1 October, aiming to finish by mid-November; the beaches stay open throughout.',
  'The City of Cape Town begins its annual beach-lowering programme on Thursday 1 October, with the aim of wrapping up by mid-November, before the festive season. Work will cover Muizenberg between the Zandvlei River mouth and the Pavilion, the section of Fish Hoek beach stretching from Jager''s Walk up to the lifesaving building, and the stretch of Hout Bay beach next to Beach Road.

Using both machinery and hand labour, crews push built-up sand down towards the low-water mark, where the waves carry it back into the coastal system. The City says this reduces the amount of sand blown onto nearby roads and infrastructure by summer winds. Hout Bay is getting extra attention this year after strong south-easterly winds arrived earlier than usual and piled up sand.

According to the City, the practice copies natural scouring and has been used for decades without any measurable effect on the environment.

All three beaches remain open while the work is under way. Visitors are asked to stay well clear of the machines and to keep dogs on a leash.',
  NULL, NULL, NULL,
  '["https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/Annual-beach-lowering-at-Muizenberg-Fish-Hoek-and-Hout-Bay?category=Media%20releases", "https://smilefm.co.za/cape-town-to-commence-with-annual-beach-lowering/"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'fire-service-adds-wildland-vehicles-summer-2026-09-30',
  'Fire and Rescue Service adds new wildfire 4x4s and staff ahead of a dry summer',
  'Community', '2026-09-30', 'City of Cape Town',
  'https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/City-s-Fire-and-Rescue-Service-prepares-for-busy-summer-season?category=Media%20releases',
  'Cape Town''s Fire and Rescue Service has added 11 new wildland 4x4 vehicles and plans to spend more than R25 million on firefighting capacity this financial year.',
  'The City of Cape Town''s Fire and Rescue Service says it is ready for what is expected to be a demanding summer fire season. Eleven new medium wildland 4x4 vehicles have joined the fleet, built to reach steep and sandy ground where full-size fire engines cannot go, and two more wildland vehicles are on the way.

The City plans to spend more than R25 million on firefighting capacity during this financial year. This includes R12 million for upgrades at the Brooklyn and Constantia fire stations and R3 million for initial work on a new fire station in Langa. On the staffing side, 35 junior firefighters finished their cadet training in July, and seasonal wildland firefighters are taken on during the warmer months.

EWN reports that the service attended nearly 31,000 fires in the 2025/26 financial year, and that the City is expecting dry vegetation, strong winds and patchy rainfall in the months ahead.

Residents are urged to practise fire safety at home. To report a fire from a cellphone, call 021 480 7700.',
  NULL, NULL, NULL,
  '["https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/City-s-Fire-and-Rescue-Service-prepares-for-busy-summer-season?category=Media%20releases", "https://www.ewn.co.za/2026/10/01/coct-strengthens-firefighting-capacity-ahead-of-high-risk-summer-fire-season"]',
  'agent'
);
